CREATE TABLE public.reels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), caption text NOT NULL DEFAULT '' CHECK(length(caption)<=500), video_path text NOT NULL CHECK(video_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(mp4|webm|mov)$'), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.reels TO authenticated; GRANT SELECT ON public.reels TO anon; GRANT ALL ON public.reels TO service_role;
ALTER TABLE public.reels ENABLE ROW LEVEL SECURITY;
CREATE POLICY reels_read ON public.reels FOR SELECT TO anon,authenticated USING(published OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY reels_add ON public.reels FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND split_part(video_path,'/',1)=auth.uid()::text);
CREATE POLICY reels_remove ON public.reels FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX reels_feed ON public.reels(created_at DESC) WHERE published;
CREATE TABLE public.reels_battle (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120), reel_a uuid NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE, reel_b uuid NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE, ends_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(reel_a<>reel_b));
GRANT SELECT,INSERT,DELETE ON public.reels_battle TO authenticated; GRANT SELECT ON public.reels_battle TO anon; GRANT ALL ON public.reels_battle TO service_role;
ALTER TABLE public.reels_battle ENABLE ROW LEVEL SECURITY;
CREATE POLICY battles_read ON public.reels_battle FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_a AND r.published) AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_b AND r.published));
CREATE POLICY battles_add ON public.reels_battle FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_a AND r.user_id=auth.uid() AND r.published) AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_b AND r.user_id=auth.uid() AND r.published));
CREATE POLICY battles_remove ON public.reels_battle FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.guard_reel_battle_deadline() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.ends_at<=now() THEN RAISE EXCEPTION 'BATTLE_ENDED'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reel_battle_deadline BEFORE INSERT ON public.reels_battle FOR EACH ROW EXECUTE FUNCTION public.guard_reel_battle_deadline();
CREATE TABLE public.reel_battle_votes (battle_id uuid NOT NULL REFERENCES public.reels_battle(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), reel_id uuid NOT NULL REFERENCES public.reels(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(battle_id,user_id));
GRANT SELECT,INSERT ON public.reel_battle_votes TO authenticated; GRANT ALL ON public.reel_battle_votes TO service_role;
ALTER TABLE public.reel_battle_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY votes_own_read ON public.reel_battle_votes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY votes_add ON public.reel_battle_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND EXISTS(SELECT 1 FROM public.reels_battle b WHERE b.id=battle_id AND b.ends_at>now() AND reel_id IN(b.reel_a,b.reel_b)));
CREATE TABLE public.comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), post_id uuid REFERENCES public.posts(id) ON DELETE CASCADE, reel_id uuid REFERENCES public.reels(id) ON DELETE CASCADE, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(post_id,reel_id)=1));
GRANT SELECT,INSERT,DELETE ON public.comments TO authenticated; GRANT SELECT ON public.comments TO anon; GRANT ALL ON public.comments TO service_role;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.comments FOR SELECT TO anon,authenticated USING((reel_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_id AND r.published)) OR (post_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=post_id AND public.post_listing_visible(p))));
CREATE POLICY comments_add ON public.comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND ((reel_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_id AND r.published)) OR (post_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=post_id AND public.post_listing_visible(p)))));
CREATE POLICY comments_remove ON public.comments FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.likes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), post_id uuid REFERENCES public.posts(id) ON DELETE CASCADE, reel_id uuid REFERENCES public.reels(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(post_id,reel_id)=1));
GRANT SELECT,INSERT,DELETE ON public.likes TO authenticated; GRANT ALL ON public.likes TO service_role;
ALTER TABLE public.likes ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX likes_post_once ON public.likes(user_id,post_id) WHERE post_id IS NOT NULL; CREATE UNIQUE INDEX likes_reel_once ON public.likes(user_id,reel_id) WHERE reel_id IS NOT NULL;
CREATE POLICY likes_own_read ON public.likes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY likes_add ON public.likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND ((reel_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=reel_id AND r.published)) OR (post_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=post_id AND public.post_listing_visible(p)))));
CREATE POLICY likes_remove ON public.likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE INDEX comments_post ON public.comments(post_id,created_at); CREATE INDEX comments_reel ON public.comments(reel_id,created_at);
CREATE FUNCTION public.social_like_count(_post uuid DEFAULT NULL,_reel uuid DEFAULT NULL) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.likes l WHERE ((_reel IS NOT NULL AND _post IS NULL AND l.reel_id=_reel AND EXISTS(SELECT 1 FROM public.reels r WHERE r.id=_reel AND r.published)) OR (_post IS NOT NULL AND _reel IS NULL AND l.post_id=_post AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND public.post_listing_visible(p)))) $$;
CREATE FUNCTION public.reel_battle_results(_battle uuid) RETURNS TABLE(reel_id uuid,votes bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,count(v.user_id) FROM public.reels_battle b JOIN public.reels r ON r.id IN(b.reel_a,b.reel_b) LEFT JOIN public.reel_battle_votes v ON v.battle_id=b.id AND v.reel_id=r.id WHERE b.id=_battle AND r.published AND EXISTS(SELECT 1 FROM public.reels a WHERE a.id=b.reel_a AND a.published) AND EXISTS(SELECT 1 FROM public.reels c WHERE c.id=b.reel_b AND c.published) GROUP BY r.id $$;
REVOKE ALL ON FUNCTION public.social_like_count(uuid,uuid),public.reel_battle_results(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.social_like_count(uuid,uuid),public.reel_battle_results(uuid) TO anon,authenticated,service_role;
CREATE POLICY reel_video_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='reel-videos' AND (owner_id=auth.uid()::text OR EXISTS(SELECT 1 FROM public.reels r WHERE r.video_path=name AND r.published)));
CREATE POLICY reel_video_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='reel-videos' AND (storage.foldername(name))[1]=auth.uid()::text AND public.account_allowed(auth.uid()));
CREATE POLICY reel_video_remove ON storage.objects FOR DELETE TO authenticated USING(bucket_id='reel-videos' AND (owner_id=auth.uid()::text OR public.has_role(auth.uid(),'admin')));